// UTILS MINIFICADO
function sanitizeHTML(str){const temp=document.createElement('div');temp.textContent=str;return temp.innerHTML}function debounce(func,wait){let timeout;return function executedFunction(...args){const later=function(){clearTimeout(timeout);func(...args)};clearTimeout(timeout);timeout=setTimeout(later,wait)}}function throttle(func,limit){let inThrottle;return function(){const args=arguments;const context=this;if(!inThrottle){func.apply(context,args);inThrottle=true;setTimeout(()=>inThrottle=false,limit)}}}function formatWhatsApp(text){return text.replace(/\s+/g,' ').trim()}function formatCurrency(value){return new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(value)}function validateEmail(email){const re=/^[^\s@]+@[^\s@]+\.[^\s@]+$/;return re.test(email)}function validatePhone(phone){const re=/^(\+?\d{2,3}[-.\s]?)?\(?\d{3}\)?[-.\s]?\d{3}[-.\s]?\d{4}$/;return re.test(phone)}function getURLParams(){const params=new URLSearchParams(window.location.search);return Object.fromEntries(params.entries())}function copyToClipboard(text){navigator.clipboard.writeText(text).then(()=>{showToast('Copiado!')}).catch(err=>{console.error('Erro ao copiar:',err)})}function showToast(message){const toast=document.createElement('div');toast.className='toast';toast.textContent=message;document.body.appendChild(toast);setTimeout(()=>toast.remove(),3000)}
